class Base { }
class Bonus extends Base {
    int points;
    Bonus(int points) { this.points = points; }
}
public class Main {
    static int sumBonuses(Base[] entries) {
        int total = 0;
        for (Base item : entries) {
            if (item instanceof Bonus bonus) {
                total = total + bonus.points;
            }
        }
        return total;
    }
    public static void main(String[] args) {
        Base[] items = {new Base(), new Bonus(3)};
        System.out.println(sumBonuses(items));
    }
}

