import java.util.Scanner;
public class Harness {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Base[] entries = new Base[n];
        for (int i = 0; i < n; i++) {
            String kind = in.next();
            if (kind.equals("B")) entries[i] = new Bonus(in.nextInt());
            else entries[i] = new Base();
        }
        System.out.println(Main.sumBonuses(entries));
    }
}
